import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), m = nextInt();
        long sa = 0, sb = 0, za = 0, zb = 0;
        for (int i = 0; i < n; i++) {
            long x = nextLong();
            sa += x;
            if (x == 0) za++;
        }
        for (int i = 0; i < m; i++) {
            long x = nextLong();
            sb += x;
            if (x == 0) zb++;
        }
        // Each team can reach every total in [s+z, s+10000z]; intersect the two ranges.
        long lo = Math.max(sa + za, sb + zb), hi = Math.min(sa + 10000 * za, sb + 10000 * zb);
        System.out.println(lo <= hi ? lo : -1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(nextInt()), int(nextInt())
	var sa, sb, za, zb int64
	for i := 0; i < n; i++ {
		x := nextInt()
		sa += x
		if x == 0 {
			za++
		}
	}
	for i := 0; i < m; i++ {
		x := nextInt()
		sb += x
		if x == 0 {
			zb++
		}
	}
	// Each team can reach every total in [s+z, s+10000z]; intersect the two ranges.
	lo, hi := max(sa+za, sb+zb), min(sa+10000*za, sb+10000*zb)
	if lo <= hi {
		fmt.Println(lo)
	} else {
		fmt.Println(-1)
	}
}
